export const EVENT_FAMILIES={window:'창밖의 손님',hygiene:'위생 조사',supplies:'재료 실험',habitat:'숲 탐사',weather:'날씨 관찰',rescue:'손님 구조',request:'관찰 의뢰',workshop:'설비 점검',exchange:'브리더 교류',night:'야간 발견'};
export const EVENT_TEMPLATES=Object.entries(STORIES).flatMap(([family,stories])=>stories.map(([title,scene],i)=>({id:`${family}-${i}`,family,title,scene,waitHours:2+i%3,guest:family==='window'||family==='night'||family==='rescue'&&i%2===0,activity:['request','exchange','habitat'].includes(family)?['care','capture','brood'][i%3]:null,goal:1+i%2,reward:120+i*15})));
export const EVENT_CATALOG=EVENT_TEMPLATES.flatMap(t=>Object.keys(SPECIES).map(species=>({...t,key:`${t.id}:${species}`,species})));
export const EVENT_BY_KEY=Object.fromEntries(EVENT_CATALOG.map(t=>[t.key,t]));

