export function eventTrial(index){const n=3+index%9;return {clue:`보조 시료 검사 ${index+1}: 빈 용기는 ${n}g, 내용물을 담은 용기는 ${n+17+index}g이에요. 기록할 내용물의 무게를 골라주세요.`,options:[`${17+index}g`,`${17+index+n}g`,`${17+index-n}g`,`${17+index+2*n}g`],answer:0};}
